import{_ as e,c as a,a2 as _,o as p}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二百四十七章 什么法是随时在变化的？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/247第二百四十七章 什么法是随时在变化的？.md","filePath":"meditation/巴利文大藏经/247第二百四十七章 什么法是随时在变化的？.md"}'),o={name:"meditation/巴利文大藏经/247第二百四十七章 什么法是随时在变化的？.md"};function r(n,t,i,s,d,c){return p(),a("div",null,t[0]||(t[0]=[_('<h1 id="第二百四十七章-什么法是随时在变化的" tabindex="-1">第二百四十七章 什么法是随时在变化的？ <a class="header-anchor" href="#第二百四十七章-什么法是随时在变化的" aria-label="Permalink to &quot;第二百四十七章 什么法是随时在变化的？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部22相应37经/阿难经(蕴相应/蕴篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，阿难尊者来到佛陀的住所，他顶礼佛陀后就在一旁坐下，佛陀对阿难尊者说：“阿难！如果有人这样问你：「阿难学友！世间什么法是会生起、存续、灭尽、变化的？修行人要明白什么的生起、存续、灭尽、变化才能开启解脱的智慧，才能从世间解脱出来？」 阿难！当你被这样问的时候，你会怎么回答呢？”</p><p>阿难尊者说：“世尊，如果有人问我这个问题，我会这样的回答：「物质事物是会生起、形成、存续、发展、衰败、灭亡、消失的，物质事物随时都在变化；物质身体会出生、成长、生病、衰老、死亡。物质身体随时都在变化。</p><p>感受、念想、行为、认识、分别、判断是会生起、出现、存续、消退、灭尽、消失的，感受、念想、行为、认识、分别、判断随时都在变化。</p><p>修行人应该要明白物质事物的生起、形成、存续、发展、衰败、灭亡、消失；要明白物质身体的出生、成长、生病、衰老、死亡；要明白感受、念想、行为、认识、分别、判断的生起、出现、存续、消退、灭尽、消失；修行人应该要明白这些事物都是随时在变化的。只有当他们知道这些事物是无法永远存在的，是无法永恒保持不变的，是无法永远拥有的，他们才会逐渐的除灭对这些事物的贪欲、渴爱，才能除灭由这些事物生起的一切烦恼和痛苦，才能不执着和挂念这些事物，从这些事物中彻底的解脱出来，他们才能开启解脱的智慧，他们才能证悟解脱的果位，从生死轮回中永远的解脱出来，达到不生不灭涅槃的境界。」”</p><p>佛陀说：“阿难！很好！很好！你已经明白了如来的教导，你就应该这样去修行。世间的人如果问你这个问题，你就应该这样去回答他们。”</p><p>佛陀说法后，阿难尊者再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，并按着佛陀所说的法去修行。</p>',9)]))}const f=e(o,[["render",r]]);export{m as __pageData,f as default};
